# -*- coding: utf-8 -*-
"""Scenario definitions SC-01 .. SC-05."""

def fleet(ids, endurance=26, payload=2.0, sensors=("RGB", "thermal"), model="M20-quad", cruise=12):
    out = []
    for i, uid in enumerate(ids):
        out.append(dict(uav_id=uid, model=model, payload_kg=payload, endurance_min=endurance,
                        cruise_mps=cruise, sensors=list(sensors),
                        role="lead" if i == 0 else "member"))
    return out


